`timescale 1ns/1ps
// Generated by uvmgen from the verification plan. Do not edit.
module tb;
    logic pclk = 1'b0;
    logic presetn = 1'b0;
    logic psel;
    logic penable;
    logic pwrite;
    logic [3:0] paddr;
    logic [31:0] pwdata;
    logic [31:0] prdata;
    logic [31:0] exp_prdata;
    bit   chk_prdata;
    logic pready;
    logic exp_pready;
    bit   chk_pready;
    logic pslverr;
    logic exp_pslverr;
    bit   chk_pslverr;

    apb_regs dut (.pclk(pclk), .presetn(presetn), .psel(psel), .penable(penable), .pwrite(pwrite), .paddr(paddr), .pwdata(pwdata), .prdata(prdata), .pready(pready), .pslverr(pslverr));

    always #5.0 pclk = ~pclk;

    // ---------------- reference model ----------------
    logic [7:0]  m_ctrl;
    logic [31:0] m_data;
    logic [15:0] m_wcnt;
    logic [1:0]  m_stat;
    bit m_access, m_mapped;
    bit m_dirty_at_reset;
    function automatic void m_reset();
        m_dirty_at_reset = (m_ctrl != 8'h00) || (m_data != 32'h0) || (m_wcnt != 16'h0) || (m_stat != 2'b00);
        m_ctrl = 8'h00;
        m_data = 32'h0;
        m_wcnt = 16'h0;
        m_stat = 2'b00;
    endfunction
    function automatic void m_outputs();
        chk_prdata = 1'b1;
        chk_pready = 1'b1;
        chk_pslverr = 1'b1;
        m_access = psel && penable;
        m_mapped = (paddr == 4'h0) || (paddr == 4'h4) || (paddr == 4'h8) || (paddr == 4'hC);
        exp_pready  = 1'b1;
        exp_pslverr = m_access && (!m_mapped || (pwrite && paddr == 4'h8));
        case (paddr)
            4'h0:    exp_prdata = {24'h0, m_ctrl};
            4'h4:    exp_prdata = m_data;
            4'h8:    exp_prdata = {16'h0, m_wcnt};
            4'hC:    exp_prdata = {30'h0, m_stat};
            default: exp_prdata = 32'h0;
        endcase
        // prdata is only defined in the access phase of a successful read
        chk_prdata = m_access && !pwrite && !exp_pslverr;
    endfunction
    function automatic void m_step();
        if (m_access && pwrite && !exp_pslverr) begin
            case (paddr)
                4'h0: begin m_ctrl = pwdata[7:0]; m_stat[1] = 1'b1; end
                4'h4: begin m_data = pwdata; m_wcnt = m_wcnt + 16'h1; m_stat[0] = 1'b1; end
                4'hC: m_stat = m_stat & ~pwdata[1:0];
                default: ;
            endcase
        end
    endfunction

    // ---------------- sequence variables ----------------
    int i;
    logic [3:0] s_addr;
    bit s_wr;
    logic [31:0] s_data;

    // ---------------- scoreboard + coverage ----------------
    int cov_hits [11];
    int errors = 0, checks = 0, cyc = 0;
    string cur_seq;
    task automatic check();
        m_outputs();
        checks++;
        if (chk_prdata && (prdata !== exp_prdata)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=prdata got=%0h exp=%0h | presetn=%0b psel=%0h penable=%0h pwrite=%0h paddr=%0h pwdata=%0h", cyc, cur_seq, i, prdata, exp_prdata, presetn, psel, penable, pwrite, paddr, pwdata);
        end
        if (chk_pready && (pready !== exp_pready)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=pready got=%0h exp=%0h | presetn=%0b psel=%0h penable=%0h pwrite=%0h paddr=%0h pwdata=%0h", cyc, cur_seq, i, pready, exp_pready, presetn, psel, penable, pwrite, paddr, pwdata);
        end
        if (chk_pslverr && (pslverr !== exp_pslverr)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=pslverr got=%0h exp=%0h | presetn=%0b psel=%0h penable=%0h pwrite=%0h paddr=%0h pwdata=%0h", cyc, cur_seq, i, pslverr, exp_pslverr, presetn, psel, penable, pwrite, paddr, pwdata);
        end
        if (psel && penable && pwrite && paddr == 4'h0) cov_hits[0]++;
        if (psel && penable && pwrite && paddr == 4'h4) cov_hits[1]++;
        if (psel && penable && pwrite && paddr == 4'hC && (pwdata[1:0] & m_stat) != 2'b00) cov_hits[2]++;
        if (psel && penable && !pwrite && paddr == 4'h0) cov_hits[3]++;
        if (psel && penable && !pwrite && paddr == 4'h4) cov_hits[4]++;
        if (psel && penable && !pwrite && paddr == 4'h8 && m_wcnt != 16'h0) cov_hits[5]++;
        if (psel && penable && !pwrite && paddr == 4'hC && m_stat == 2'b11) cov_hits[6]++;
        if (pslverr && pwrite && paddr == 4'h8) cov_hits[7]++;
        if (pslverr && paddr != 4'h0 && paddr != 4'h4 && paddr != 4'h8 && paddr != 4'hC) cov_hits[8]++;
        if (!psel) cov_hits[9]++;
        if (!presetn && m_dirty_at_reset) cov_hits[10]++;
    endtask

    task automatic drive_defaults();
        psel = 1'b0;
        penable = 1'b0;
        pwrite = 1'b0;
        paddr = 4'h0;
        pwdata = 32'h0;
    endtask

    initial begin
        drive_defaults();
        presetn = 1'b0;
        m_reset();
        repeat (3) @(negedge pclk);
        presetn = 1'b1;

        // sequence: random_mapped_transfers
        cur_seq = "random_mapped_transfers";
        for (i = 0; i < 4000; i++) begin
            @(negedge pclk);
            cyc++;
            drive_defaults();
            if (i % 2 == 0) begin
                s_addr = 4'($urandom_range(0, 3) * 4);
                s_wr   = 1'($urandom_range(0, 1));
                s_data = $urandom;
            end
            psel = 1'b1;
            penable = 1'(i % 2);
            pwrite = s_wr;
            paddr = s_addr;
            pwdata = s_data;
            presetn = 1'b1;
            #1;
            if (presetn == 1'b0) m_reset();
            check();
            @(posedge pclk);
            if (presetn != 1'b0) m_step();
        end

        // sequence: all_addresses_with_idle
        cur_seq = "all_addresses_with_idle";
        for (i = 0; i < 3000; i++) begin
            @(negedge pclk);
            cyc++;
            drive_defaults();
            if (i % 3 == 0) begin
                s_addr = 4'($urandom_range(0, 15));
                s_wr   = 1'($urandom_range(0, 1));
                s_data = $urandom;
            end
            psel = 1'(i % 3 != 2);
            penable = 1'(i % 3 == 1);
            pwrite = s_wr;
            paddr = s_addr;
            pwdata = s_data;
            presetn = 1'b1;
            #1;
            if (presetn == 1'b0) m_reset();
            check();
            @(posedge pclk);
            if (presetn != 1'b0) m_step();
        end

        // sequence: reset_then_read_all
        cur_seq = "reset_then_read_all";
        for (i = 0; i < 400; i++) begin
            @(negedge pclk);
            cyc++;
            drive_defaults();
            if (i % 2 == 0) begin
                // every 40 cycles: 10 random writes, reset, then read all four registers
                s_wr   = 1'((i % 40) < 20);
                s_addr = 4'((i % 8) * 2);
                s_data = $urandom;
            end
            psel = 1'b1;
            penable = 1'(i % 2);
            pwrite = s_wr;
            paddr = s_addr;
            pwdata = s_data;
            presetn = ((i % 40) == 20) ? 1'b0 : 1'b1;
            #1;
            if (presetn == 1'b0) m_reset();
            check();
            @(posedge pclk);
            if (presetn != 1'b0) m_step();
        end

        $display("COVER write_ctrl %0d", cov_hits[0]);
        $display("COVER write_data %0d", cov_hits[1]);
        $display("COVER write_stat_clear %0d", cov_hits[2]);
        $display("COVER read_ctrl %0d", cov_hits[3]);
        $display("COVER read_data %0d", cov_hits[4]);
        $display("COVER read_wcnt %0d", cov_hits[5]);
        $display("COVER read_stat_set %0d", cov_hits[6]);
        $display("COVER error_write_wcnt %0d", cov_hits[7]);
        $display("COVER error_unmapped %0d", cov_hits[8]);
        $display("COVER idle_cycle %0d", cov_hits[9]);
        $display("COVER reset_after_writes %0d", cov_hits[10]);
        $display("CHECKS %0d ERRORS %0d", checks, errors);
        if (errors == 0) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
